-- Generated by Better Auth's getMigrations from the pinned plugin set
-- organization() + twoFactor() + passkey() + jwt() + mcp() + scim() (the SCIM
-- plugin from @better-auth/scim@1.7.3, application-owned bearer verification,
-- no managed connection catalog), against a scratch database migrated through
-- provider 0001..0010, then pasted. Hand edits:
--   - the `bakery_app` grant: the runtime role owns nothing (0002). The plugin
--     stores provisioned SCIM users, groups and projection state; credentials
--     live in bakery.scim_credentials, not here.
create table "scimConnectionBinding" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "connectionId" text not null, "connectionKey" text not null unique, "provisioningDomainId" text not null, "createdAt" timestamptz not null, "decommissionedAt" timestamptz, "decommissionStatus" text not null, "decommissionCursorUserId" text, "decommissionReconciledUserCount" integer not null, "decommissionBatchCount" integer not null, "decommissionRevision" integer not null, "decommissionCompletedAt" timestamptz, "decommissionLeaseId" text, "decommissionLeaseExpiresAt" timestamptz);

create table "scimIdentityTombstone" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "connectionId" text not null, "provisioningDomainId" text not null, "externalId" text not null, "externalIdKey" text not null unique, "userId" uuid not null references "user" ("id") on delete cascade, "profile" text not null, "deletedAt" timestamptz not null);

create table "scimSubject" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "userId" uuid not null unique references "user" ("id") on delete cascade, "profileSourceId" text, "revision" integer not null, "createdAt" timestamptz not null, "updatedAt" timestamptz not null);

create table "scimUser" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "connectionId" text not null, "provisioningDomainId" text not null, "userId" uuid not null references "user" ("id") on delete cascade, "connectionUserKey" text not null unique, "userName" text not null, "userNameKey" text not null unique, "primaryEmail" text not null, "workEmailValueIndex" text not null, "emailValueIndex" text not null, "displayName" text not null, "formattedName" text not null, "givenName" text, "familyName" text, "serializedEmails" text not null, "serializedAttributes" text, "externalId" text, "externalIdKey" text unique, "active" boolean not null, "orderKey" text not null unique, "createdAt" timestamptz not null, "updatedAt" timestamptz not null);

create table "scimProjectionGrant" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "connectionId" text not null, "provisioningDomainId" text not null, "scimUserId" uuid not null references "scimUser" ("id") on delete cascade, "userId" uuid not null references "user" ("id") on delete cascade, "sourceKind" text not null, "sourceId" text not null, "sourceValue" text, "role" text not null, "grantKey" text not null unique, "createdAt" timestamptz not null, "updatedAt" timestamptz not null);

create table "scimGroup" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "connectionId" text not null, "provisioningDomainId" text not null, "revision" integer not null, "displayName" text not null, "displayNameKey" text not null unique, "externalId" text, "externalIdKey" text unique, "orderKey" text not null unique, "createdAt" timestamptz not null, "updatedAt" timestamptz not null);

create table "scimGroupMember" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "connectionId" text not null, "groupId" uuid not null references "scimGroup" ("id") on delete cascade, "scimUserId" uuid not null references "scimUser" ("id") on delete cascade, "membershipKey" text not null unique, "createdAt" timestamptz not null);

create index "scimConnectionBinding_connectionId_idx" on "scimConnectionBinding" ("connectionId");

create index "scimIdentityTombstone_connectionId_idx" on "scimIdentityTombstone" ("connectionId");

create index "scimIdentityTombstone_provisioningDomainId_idx" on "scimIdentityTombstone" ("provisioningDomainId");

create index "scimIdentityTombstone_userId_idx" on "scimIdentityTombstone" ("userId");

create index "scimSubject_profileSourceId_idx" on "scimSubject" ("profileSourceId");

create index "scimUser_connectionId_idx" on "scimUser" ("connectionId");

create index "scimUser_provisioningDomainId_idx" on "scimUser" ("provisioningDomainId");

create index "scimUser_userId_idx" on "scimUser" ("userId");

create index "scimProjectionGrant_connectionId_idx" on "scimProjectionGrant" ("connectionId");

create index "scimProjectionGrant_provisioningDomainId_idx" on "scimProjectionGrant" ("provisioningDomainId");

create index "scimProjectionGrant_scimUserId_idx" on "scimProjectionGrant" ("scimUserId");

create index "scimProjectionGrant_userId_idx" on "scimProjectionGrant" ("userId");

create index "scimGroup_connectionId_idx" on "scimGroup" ("connectionId");

create index "scimGroup_provisioningDomainId_idx" on "scimGroup" ("provisioningDomainId");

create index "scimGroupMember_connectionId_idx" on "scimGroupMember" ("connectionId");

create index "scimGroupMember_groupId_idx" on "scimGroupMember" ("groupId");

create index "scimGroupMember_scimUserId_idx" on "scimGroupMember" ("scimUserId");

grant select, insert, update, delete
on table
  public."scimConnectionBinding",
  public."scimIdentityTombstone",
  public."scimSubject",
  public."scimUser",
  public."scimProjectionGrant",
  public."scimGroup",
  public."scimGroupMember"
to bakery_app;
